<script>
 import {onMount} from 'svelte';
 import {locale} from '$lib/i18n.js';
 import {listDevices} from '$lib/api.js';
 import {notify} from '$lib/stores.js';
 let devices=[],limit=1,loading=true;
 $: ru=$locale!=='en';
 const setupCommand='yevqo-setup';
 async function copyCommand(){try{await navigator.clipboard.writeText(setupCommand);notify(ru?'Команда скопирована':'Command copied','success')}catch{notify(ru?'Не удалось скопировать':'Could not copy command','error')}}
 onMount(async()=>{const r=await listDevices();if(r.ok){devices=r.data.devices||[];limit=r.data.limit||1}else notify(r.error||'Could not load devices','error');loading=false});
</script>
<svelte:head><title>{ru?'Подключить устройство':'Connect device'} · Yevqo</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE / DEVICE PAIRING</div><h1 class="page-title">{ru?'Подключить устройство':'Connect a device'}</h1><p class="page-desc">{ru?'Добавь Android-устройство через Yevqo Agent и безопасный pairing token.':'Connect an Android device using Yevqo Agent and a secure pairing token.'}</p></div><a class="back" href="/devices">← {ru?'Устройства':'Devices'}</a></div>
{#if loading}<div class="empty">{ru?'Проверяем лимит…':'Checking device allowance…'}</div>{:else}
<section class="connect-card"><div class="step-head"><span class="step-number">01</span><div><h2>{ru?'Проверь лимит устройств':'Check your device allowance'}</h2><p>{ru?'Текущее использование подключений':'Current connected device usage'}</p></div></div><div class="limit-line"><strong>{devices.length} / {limit}</strong><span>{ru?'подключённых устройств':'connected devices'}</span></div>{#if devices.length>=limit}<div class="warning">{ru?'Лимит достигнут. Сначала отвяжи существующее устройство.':'The device limit is reached. Unpair an existing device first.'}</div>{/if}</section>
<section class="connect-card"><div class="step-head"><span class="step-number">02</span><div><h2>{ru?'Установи Yevqo Agent':'Install Yevqo Agent'}</h2><p>{ru?'Установи пакет Yevqo для Termux на Android-устройство.':'Install the Yevqo Termux package on your Android device.'}</p></div></div><ol><li>{ru?'Установи Termux из поддерживаемого источника и открой приложение.':'Install Termux from a supported source and open it.'}</li><li>{ru?'Установи ARM64 пакет Yevqo, который включает Agent.':'Install the ARM64 Yevqo package that includes the Agent.'}</li><li>{ru?'Если Android запросит доступ к общему хранилищу, выполни termux-setup-storage.':'If Android requests shared storage access, run termux-setup-storage.'}</li></ol></section>
<section class="connect-card"><div class="step-head"><span class="step-number">03</span><div><h2>{ru?'Запусти мастер подключения':'Run the connection setup'}</h2><p>{ru?'Мастер сам создаст конфигурацию и настроит службу.':'The setup wizard creates the config and configures the service.'}</p></div></div><div class="command"><code>{setupCommand}</code><button on:click={copyCommand}>{ru?'Копировать':'Copy'}</button></div><p class="hint">{ru?'Мастер запросит WebSocket URL панели и Agent pairing token. Используй адрес, заканчивающийся на /ws, и токен из профиля Yevqo.':'The wizard asks for the Control Plane WebSocket URL and your Agent pairing token. Use the panel address ending in /ws and the token from your Yevqo profile.'}</p><a class="profile-link" href="/profile">{ru?'Открыть профиль и создать pairing token':'Open profile and create an Agent pairing token'} →</a></section>
<section class="connect-card"><div class="step-head"><span class="step-number">04</span><div><h2>{ru?'Проверь подключение':'Verify the connection'}</h2><p>{ru?'Устройство появится в списке только после успешного handshake Agent.':'The device appears only after the Agent completes its authenticated handshake.'}</p></div></div><div class="verify-command"><code>sv status yevqo-agent</code><code>svlogtail yevqo-agent</code></div><p class="hint">{ru?'Имя службы зависит от выбранного пакета и мастера установки. Используй команду статуса, которую мастер вывел после настройки. Не считай устройство подключённым, пока оно не появится в Devices со статусом Online.':'The service name depends on the selected package/setup mode. Use the status command printed by the installer. Do not consider the device connected until it appears in Devices with Online status.'}</p><a class="profile-link" href="/devices">{ru?'Открыть список устройств':'Open devices'} →</a></section>
{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:var(--accent);font-weight:700;margin-bottom:7px}.back{font-size:10px;color:var(--text-muted)}.connect-card{padding:17px;margin-bottom:12px;border:1px solid var(--border);border-radius:10px;background:var(--bg-card)}.step-head{display:flex;align-items:flex-start;gap:11px;margin-bottom:13px}.step-number{width:28px;height:28px;display:grid;place-items:center;border:1px solid var(--border);border-radius:7px;color:var(--accent);font:11px var(--mono)}.step-head h2{font-size:12px;margin-bottom:4px}.step-head p,.hint{font-size:10px;color:var(--text-muted);line-height:1.65}.limit-line{display:flex;align-items:baseline;gap:8px}.limit-line strong{font-size:22px}.limit-line span{font-size:10px;color:var(--text-muted)}.warning{margin-top:10px;padding:10px;border:1px solid #E9B85C55;border-radius:7px;color:var(--warning);font-size:10px}.connect-card ol{padding-left:39px}.connect-card li{padding:4px 0;color:var(--text-muted);font-size:10px;line-height:1.6}.command,.verify-command{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid var(--border);border-radius:7px;background:var(--bg-input)}.command code,.verify-command code{font:11px var(--mono);color:var(--text-main)}.command button{margin-left:auto;padding:6px 9px;border:1px solid var(--border);border-radius:6px;background:var(--bg-elevated);color:var(--accent);font-size:9px}.hint{margin-top:10px}.profile-link{display:inline-block;margin-top:10px;color:var(--accent);font-size:10px}.verify-command{justify-content:flex-start;flex-wrap:wrap}.verify-command code{padding:3px 0}
</style>